using System.Collections.Generic;
using Verse;

namespace AnimalCosmeticGenes
{
    /// <summary>
    /// A list of gene defName to trait. Generated by Tests/Generate-CoatTraits.ps1, so a new gene or a new mod is one run
    /// of the script. The gene is a text and not a reference: genes of a mod that is not loaded are never found, and genes
    /// the game builds from a template (Biotech hair colours, melanin) exist after XML patches, so no patch could reach them.
    /// </summary>
    public class GeneTraitMapDef : Def
    {
        public List<GeneTraitMapping> mappings = new List<GeneTraitMapping>();
    }

    public class GeneTraitMapping
    {
        public string gene;
        public HediffDef trait;
    }
}
